      OFFICE_BUSY:L('İki iş zaten çalışıyor. Biri tamamlanınca tekrar deneyin.','Two jobs are already running. Try again when one completes.'),
      OFFICE_ARCHIVE_BATCH_LIMIT:L('Geçerli bir başlangıç parçası ve en fazla 15 parça seçin. Sonraki gruplar ayrı onayla incelenir; arşiv korunur.','Choose a valid first part and at most 15 parts. Later batches require separate approval; the archive remains intact.'),
      OFFICE_MEMORY_CONFLICT:L('Aynı anahtardaki çelişen hafızalardan yalnız birini seçin.','Select only one conflicting memory for each key.'),
      OFFICE_AUTOMATION_SCOPE:L('Bu araç yalnız desteklenen Buyer Log analizleri, uygulama işlemleri ve mail taslaklarını çalıştırır.','This tool runs only supported Buyer Log analyses, app actions and email drafts.'),
      OFFICE_AUTOMATION_VERIFY_FAILED:L('Otomasyonun gerçek sonucu doğrulanamadı. Çalışma kaydını kontrol edin.','The actual automation result could not be verified. Check the run record.'),
      AUTOMATION_RECIPE_LIMIT:L('160 otomasyon sınırına ulaşıldı. Mevcut bir tarifi düzenleyin veya kaldırın.','The 160-automation limit was reached. Edit or remove an existing recipe.'),
      AUTOMATION_DISABLED:L('Tarifi ayrı bir onayla etkinleştirin.','Activate the recipe with a separate approval.'),
      AUTOMATION_NOT_FOUND:L('Otomasyon bulunamadı veya size ait değil.','The automation was not found or is not yours.'),
      OFFICE_SCHEDULE_SCOPE:L('Zamanlama yetkisi veya kapsamı değişti. Yeni önizlemeyi onaylayın.','The schedule grant or scope changed. Approve a new preview.'),
      OFFICE_TIMEZONE_INVALID:L('Zamanlama saat dilimi Buyer Log sunucusunun saat dilimiyle aynı olmalı.','The schedule timezone must match the Buyer Log server timezone.'),
      AI_AUTOMATION_VALIDATION_FAILED:L('Otomasyon mevcut dil ve alan doğrulamasından geçemedi.','The automation failed current language and field validation.'),
      AI_AUTOMATION_NEEDS_REVIEW:L('Otomasyon güncel motorla uyumlu değil. Yeniden önizleyip revize edin.','The automation is incompatible with the current engine. Preview and revise it.'),
      AI_AUTOMATION_INPUT_REQUIRED:L('Kullanılacak e-posta grubunu seçin.','Select the email group to use.'),
      OFFICE_TEXT_TOO_LONG:L('Metin boyut sınırını aşıyor. Bölerek kaydedin.','The text exceeds the size limit. Save it in parts.'),
      OFFICE_OWNER_NOT_FOUND:L('Kullanıcı bulunamadı.','User not found.'),
      OFFICE_NOT_FOUND:L('Kayıt bulunamadı veya erişim kapsamınız dışında.','The record was not found or is outside your access scope.'),
      OFFICE_AGENT_LIMIT:L('Bu ofiste en fazla 24 agent bulunabilir.','An office can have up to 24 agents.'),
